"""The roster of the 35 weapons of 1.97.0 (wave 71): 13 Legend, 12 God and 10 Genesis grade relics. ONE table: tools/relics/new197_gen.py writes the Java
(relics/wave/Wave71.java, Wave71Passives.java), the lang fragment (tools/lang/new_weapons_197.json), the class tables, the theme entries and the doc from it, and
the model generators (new197_legend.py, new197_god.py, new197_genesis.py) build the meshes, skins, icons and item models of every id in it.

An entry:
  id, name, grade ('LEGEND' | 'GOD' | 'GENESIS'), cls (the weapon class of weapon_classes.json: also the GradeDamage weapon type), speed (attacks per second),
  look (Look enum), pal (main, trim, glow), theme (a mega-dungeon road, relic_themes.json), src (the franchise or tradition it comes from),
  rule (the passive: Cond, bonus, extras), attrs / resists / skills (the standing passives), lore (the tooltip sentences), acts, engr (Tensura engravings),
  kind ('melee' | 'bow' | 'crossbow'), doc (what the weapon is, for the doc), model (the generator function that builds it).
An act: key, name, expr (a function from the damage helper D(k) to the Java expression of the body), cd (seconds), mana (percent), text (what it does),
  and optionally sneak (True), day (uses per day).
"""

SWORD, RAPIER, STAFF, WAND, HAMMER, AXE, BOW, SHIELD, GAUNTLETS = "SWORD", "RAPIER", "STAFF", "WAND", "HAMMER", "AXE", "BOW", "SHIELD", "GAUNTLETS"
PA = '"minecraft:player_attack"'
MG = '"minecraft:magic"'
FIREDMG = '"minecraft:in_fire"'
FREEZE = '"minecraft:freeze"'
LIGHTNING = '"minecraft:lightning_bolt"'
DROWN = '"minecraft:drown"'
Q = lambda s: '"%s"' % s if s else "null"        # a Java string or null


def R(cond, bonus, **kw):
    return dict(cond=cond, bonus=bonus, **kw)


def A(key, name, expr, cd, mana, text, sneak=False, day=0):
    return dict(key=key, name=name, expr=expr, cd=cd, mana=mana, text=text, sneak=sneak, day=day)


